// SPDX-License-Identifier: MIT
pragma solidity ^0.8.4;

import "./Base64.sol";
import "./P256.sol";

/// @notice WebAuthn verification library.
/// @author Solady (https://github.com/vectorized/solady/blob/main/src/utils/WebAuthn.sol)
library WebAuthn {
    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                        STRUCTS                             */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Defines a struct for WebAuthn authentication data.
    ///
    /// @dev This struct is used to store WebAuthn authentication details, including:
    /// - `authenticatorData`: The WebAuthn authenticator data as per the WebAuthn specification.
    /// - `clientDataJSON`: The WebAuthn client data JSON as per the WebAuthn specification.
    /// - `challengeIndex`: The start index of the "challenge":"..." substring within `clientDataJSON`.
    /// - `typeIndex`: The start index of the "type":"..." substring within `clientDataJSON`.
    /// - `r`: The r value of the secp256r1 signature.
    /// - `s`: The s value of the secp256r1 signature.
    ///
    /// This struct is typically used in WebAuthn-based authentication mechanisms.
    struct WebAuthnAuth {
        bytes authenticatorData;
        string clientDataJSON;
        uint256 challengeIndex;
        uint256 typeIndex;
        bytes32 r;
        bytes32 s;
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                     VERIFY OPERATIONS                      */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Verifies a WebAuthn authentication challenge using the provided parameters.
    ///
    /// @param challenge The challenge bytes to be verified.
    /// @param requireUserVerification A boolean indicating whether user verification is required.
    /// @param auth A WebAuthnAuth struct containing authentication data.
    /// @param x The x-coordinate of the public key.
    /// @param y The y-coordinate of the public key.
    /// @return result A boolean indicating whether the verification was successful.
    function verify(
        bytes memory challenge,
        bool requireUserVerification,
        WebAuthnAuth memory auth,
        bytes32 x,
        bytes32 y
    ) internal view returns (bool result) {
        result = verify(
            challenge,
            requireUserVerification,
            auth.authenticatorData,
            auth.clientDataJSON,
            auth.challengeIndex,
            auth.typeIndex,
            auth.r,
            auth.s,
            x,
            y
        );
    }

    /// @notice Verifies a WebAuthn authentication challenge using the provided parameters.
    ///
    /// @param challenge The challenge bytes to be verified.
    /// @param requireUserVerification A boolean indicating whether user verification is required.
    /// @param authenticatorData The WebAuthn authenticator data as per the WebAuthn specification.
    /// @param clientDataJSON The WebAuthn client data JSON as per the WebAuthn specification.
    /// @param challengeIndex The start index of the "challenge":"..." substring within `clientDataJSON`.
    /// @param typeIndex The start index of the "type":"..." substring within `clientDataJSON`.
    /// @param r The r value of the secp256r1 signature.
    /// @param s The s value of the secp256r1 signature.
    /// @param x The x-coordinate of the public key.
    /// @param y The y-coordinate of the public key.
    /// @return result A boolean indicating whether the verification was successful.
    function verify(
        bytes memory challenge,
        bool requireUserVerification,
        bytes memory authenticatorData,
        string memory clientDataJSON,
        uint256 challengeIndex,
        uint256 typeIndex,
        bytes32 r,
        bytes32 s,
        bytes32 x,
        bytes32 y
    ) internal view returns (bool result) {
        // Encode the challenge using Base64 URL-safe encoding without padding.
        string memory encodedChallenge = Base64.encode(challenge, true, true);

        // Verify the signature by computing the hash over authenticatorData and clientDataJSON.
        result = _verify(
            encodedChallenge,
            requireUserVerification,
            authenticatorData,
            clientDataJSON,
            challengeIndex,
            typeIndex,
            r,
            s,
            x,
            y
        );
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                 ENCODE / DECODE OPERATIONS                  */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @notice Encodes a WebAuthnAuth struct into a bytes array.
    ///
    /// @param auth The WebAuthnAuth struct to be encoded.
    /// @return encoded The encoded bytes representation of the WebAuthnAuth struct.
    function encodeAuth(WebAuthnAuth memory auth) internal pure returns (bytes memory encoded) {
        encoded = abi.encode(auth);
    }

    /// @notice Attempts to decode WebAuthn authentication data from the provided encoded bytes.
    ///
    /// @param encodedAuth The encoded authentication data to be decoded.
    /// @return decoded A `WebAuthnAuth` struct containing the decoded authentication data.
    function tryDecodeAuth(bytes memory encodedAuth) internal pure returns (WebAuthnAuth memory decoded) {
        /// @solidity memory-safe-assembly
        assembly {
            let o := add(encodedAuth, 0x20)
            let e := add(o, mload(encodedAuth))

            let p := mload(o)

            // Validate authenticatorData pointer.
            if iszero(lt(add(o, p), e)) { break }
            let adLen := mload(add(o, p))
            if iszero(lt(add(add(o, p), adLen), e)) { break }

            // Validate clientDataJSON pointer.
            let cdp := mload(add(o, add(p, 0x20)))
            if iszero(lt(add(o, cdp), e)) { break }
            let cdLen := mload(add(o, cdp))
            if iszero(lt(add(add(o, cdp), cdLen), e)) { break }

            // Store authenticatorData.
            mstore(decoded, mload(add(o, p)))
            mstore(add(decoded, 0x20), mload(add(add(o, p), 0x20)))
            let adSrc := add(add(o, p), 0x20)
            let adDst := add(decoded, 0x40)
            for { let i := 0 } lt(i, adLen) { i := add(i, 0x20) } {
                mstore(add(adDst, i), mload(add(adSrc, i)))
            }

            // Store clientDataJSON.
            mstore(add(decoded, 0x40), mload(add(o, cdp)))
            let cdSrc := add(add(o, cdp), 0x20)
            let cdDst := add(add(decoded, 0x40), 0x20)
            for { let i := 0 } lt(i, cdLen) { i := add(i, 0x20) } {
                mstore(add(cdDst, i), mload(add(cdSrc, i)))
            }

            // Store challengeIndex, typeIndex, r, s.
            let base := add(o, add(p, 0x40))
            mstore(add(decoded, 0x60), mload(base))
            mstore(add(decoded, 0x80), mload(add(base, 0x20)))
            mstore(add(decoded, 0xa0), mload(add(base, 0x40)))
            mstore(add(decoded, 0xc0), mload(add(base, 0x60)))
        }
    }

    /// @notice Encodes a WebAuthnAuth struct into a compact byte array representation.
    ///
    /// @param auth The WebAuthnAuth struct to be encoded.
    /// @return result The compact byte array representation of the WebAuthnAuth struct.
    function tryEncodeAuthCompact(WebAuthnAuth memory auth) internal pure returns (bytes memory result) {
        uint256 adLen = auth.authenticatorData.length;
        uint256 cdLen = bytes(auth.clientDataJSON).length;
        uint256 ci = auth.challengeIndex;
        uint256 ti = auth.typeIndex;
        bytes32 r = auth.r;
        bytes32 s = auth.s;

        // Validate that lengths and indices fit in uint16.
        if (adLen > 0xffff || cdLen > 0xffff || ci > 0xffff || ti > 0xffff) return result;

        /// @solidity memory-safe-assembly
        assembly {
            result := mload(0x40)

            let m := add(result, 0x20)
            mstore(m, adLen)

            mcopy(add(m, 0x02), add(auth.authenticatorData, 0x20), adLen)
            m := add(m, add(0x02, adLen))

            mcopy(m, add(add(auth, 0x40), 0x20), cdLen)
            m := add(m, cdLen)

            // Store challengeIndex and typeIndex as 2 bytes each.
            mstore(m, shl(240, or(shl(16, ci), ti)))
            m := add(m, 0x04)

            mstore(m, r)
            m := add(m, 0x20)
            mstore(m, s)
            m := add(m, 0x20)

            let encLen := sub(m, add(result, 0x20))
            mstore(result, encLen)
            mstore(0x40, and(add(m, 31), not(31)))
            mstore(m, 0)
        }
    }

    /// @notice Decodes a compact WebAuthn authentication structure from a byte array.
    ///
    /// @param encodedAuth The byte array containing the encoded WebAuthn authentication data.
    /// @return decoded A `WebAuthnAuth` struct containing the decoded authentication data.
    function tryDecodeAuthCompact(bytes memory encodedAuth) internal pure returns (WebAuthnAuth memory decoded) {
        /// @solidity memory-safe-assembly
        assembly {
            if lt(mload(encodedAuth), 0x46) { break }

            let d := add(encodedAuth, 0x20)
            let end := add(d, mload(encodedAuth))

            let adLen := and(shr(240, mload(d)), 0xffff)
            let cdLenOffset := add(add(d, 0x02), adLen)
            if iszero(lt(cdLenOffset, end)) { break }

            let cdLen := and(shr(240, mload(cdLenOffset)), 0xffff)
            let ciOffset := add(cdLenOffset, cdLen)
            if iszero(lt(ciOffset, end)) { break }

            let authLen := add(add(add(adLen, cdLen), 0x04), 0x40)
            if iszero(eq(add(sub(ciOffset, add(add(d, 0x02), adLen)), authLen), mload(encodedAuth))) {
                break
            }

            // Store authenticatorData.
            mstore(decoded, adLen)
            mcopy(add(decoded, 0x20), add(d, 0x02), adLen)

            // Store clientDataJSON.
            mstore(add(decoded, 0x40), cdLen)
            mcopy(add(add(decoded, 0x40), 0x20), add(cdLenOffset, 0x02), cdLen)

            // Store challengeIndex, typeIndex, r, s.
            let base := add(ciOffset, 0x02)
            mstore(add(decoded, 0x60), and(shr(224, mload(base)), 0xffff))
            mstore(add(decoded, 0x80), and(shr(224, mload(add(base, 0x02))), 0xffff))
            mstore(add(decoded, 0xa0), mload(add(base, 0x04)))
            mstore(add(decoded, 0xc0), mload(add(base, 0x24)))
        }
    }

    /// @notice Decodes a compact WebAuthn authentication data structure from calldata.
    ///
    /// @param encodedAuth The encoded authentication data passed as calldata.
    /// @return decoded A `WebAuthnAuth` struct containing the decoded authentication data.
    function tryDecodeAuthCompactCalldata(bytes calldata encodedAuth) internal pure returns (WebAuthnAuth memory decoded) {
        /// @solidity memory-safe-assembly
        assembly {
            if lt(encodedAuth.length, 0x46) { break }

            let d := encodedAuth.offset
            let end := add(d, encodedAuth.length)

            let adLen := and(shr(240, calldataload(d)), 0xffff)
            let cdLenOffset := add(add(d, 0x02), adLen)
            if iszero(lt(cdLenOffset, end)) { break }

            let cdLen := and(shr(240, calldataload(cdLenOffset)), 0xffff)
            let ciOffset := add(cdLenOffset, cdLen)
            if iszero(lt(ciOffset, end)) { break }

            // Store authenticatorData.
            mstore(decoded, adLen)
            calldatacopy(add(decoded, 0x20), add(d, 0x02), adLen)

            // Store clientDataJSON.
            mstore(add(decoded, 0x40), cdLen)
            calldatacopy(add(add(decoded, 0x40), 0x20), add(cdLenOffset, 0x02), cdLen)

            // Store challengeIndex, typeIndex, r, s.
            let base := add(ciOffset, 0x02)
            mstore(add(decoded, 0x60), and(shr(224, calldataload(base)), 0xffff))
            mstore(add(decoded, 0x80), and(shr(224, calldataload(add(base, 0x02))), 0xffff))
            mstore(add(decoded, 0xa0), calldataload(add(base, 0x04)))
            mstore(add(decoded, 0xc0), calldataload(add(base, 0x24)))
        }
    }

    /*´:°•.°+.*•´.*:˚.°*.˚•´.°:°•.°•.*•´.*:˚.°*.˚•´.°:°•.°+.*•´.*:*/
    /*                   INTERNAL HELPERS                         */
    /*.•°:°.´+˚.*°.˚:*.´•*.+°.•°:´*.´•*.•°.•°:°.´:•˚°.*°.˚:*.´+°.•*/

    /// @dev The internal verification function.
    function _verify(
        string memory encodedChallenge,
        bool requireUserVerification,
        bytes memory authenticatorData,
        string memory clientDataJSON,
        uint256 challengeIndex,
        uint256 typeIndex,
        bytes32 r,
        bytes32 s,
        bytes32 x,
        bytes32 y
    ) private view returns (bool) {
        // The clientDataJSON should be:
        // '{"type":"webauthn.get","challenge":"...","origin":"...","crossOrigin":...}'
        //
        // We need to check:
        // 1. The "type" field is "webauthn.get".
        // 2. The "challenge" field matches the base64url-encoded challenge.
        // 3. The User Present flag (bit 0) is set in authenticatorData.
        // 4. If user verification is required, the User Verified flag (bit 2) is set.
        // 5. The Attested Credential Data flag (bit 6) is NOT set.
        // 6. The signature over SHA256(authenticatorData || clientDataJSON) is valid.

        bytes32 hash;
        /// @solidity memory-safe-assembly
        assembly {
            let m := mload(0x40)
            let clientDataJSONLen := mload(clientDataJSON)

            // Check if `clientDataJSON` has the correct "type":"webauthn.get".
            // The `typeIndex` points to the start of the value of "type" (after the colon).
            // We expect `"webauthn.get"` starting at `typeIndex + 1` (skipping the opening quote).
            let typePtr := add(add(clientDataJSON, typeIndex), 0x20)
            // The value at `typePtr` should start with `"webauthn.get"`.
            // We check the first 13 characters: "webauthn.get"
            // `"webauthn.get"` is 0x22776562617574686e2e67657422
            if iszero(eq(mload(typePtr), "webauthn.get")) {
                mstore(0x00, 0) // `false`.
                return
            }

            // Check if the `challenge` matches.
            // The `challengeIndex` points to the start of the value of "challenge" (after the colon).
            // We skip the opening quote character.
            let challengePtr := add(add(clientDataJSON, challengeIndex), 0x21)
            let encodedChallengeLen := mload(encodedChallenge)
            for { let i := 0 } 1 { i := add(i, 0x20) } {
                if iszero(lt(i, encodedChallengeLen)) {
                    // Check that the next character is a closing quote.
                    if iszero(eq(byte(0, mload(add(challengePtr, i))), 0x22)) {
                        mstore(0x00, 0) // `false`.
                        return
                    }
                    break
                }
                if iszero(eq(mload(add(challengePtr, i)), mload(add(encodedChallenge, add(i, 0x20))))) {
                    mstore(0x00, 0) // `false`.
                    return
                }
            }

            // Check if `authenticatorData` has the correct flags.
            // The first 32 bytes of `authenticatorData` (after the length) contain rpIdHash (32 bytes).
            // The flags byte is at byte offset 32.
            let flags := byte(0, mload(add(add(authenticatorData, 32), 32)))
            // User Present flag (bit 0) must be set.
            if iszero(and(flags, 0x01)) {
                mstore(0x00, 0) // `false`.
                return
            }
            // User Verified flag (bit 2) must be set if user verification is required.
            if and(requireUserVerification, iszero(and(flags, 0x04))) {
                mstore(0x00, 0) // `false`.
                return
            }
            // Attested Credential Data flag (bit 6) must NOT be set.
            if and(flags, 0x80) {
                mstore(0x00, 0) // `false`.
                return
            }

            // Compute `hash = sha256(authenticatorData || clientDataJSON)`.
            // Copy `authenticatorData` to `m`.
            let adLen := mload(authenticatorData)
            mstore(m, adLen)
            mcopy(add(m, 0x20), add(authenticatorData, 0x20), adLen)
            // Copy `clientDataJSON` to `m + adLen`.
            mcopy(add(add(m, 0x20), adLen), add(clientDataJSON, 0x20), clientDataJSONLen)
            hash := sha256(add(m, 0x20), add(adLen, clientDataJSONLen))
        }
        return P256.verifySignature(hash, r, s, x, y);
    }
}

